export function builtinTranslationGuide(locale: Locale, category: string): Guide {
  const { title, description, captureNote, sections } = copy[locale];
  return {
    slug: 'builtin-translation', title, description, captureNote, category, minutes: 7,
    published: '2026-11-01', updated: '2026-11-01',
    related: ['manga-translation', 'local-translation', 'translation-troubleshooting'],
    sections: sections.map(([title, paragraph]) => ({ title, paragraphs: [paragraph] })),
  };
}
